//! Numbers as a locale writes them (D21), from CLDR's number data
//! (generated by gen.zig): decimal and percent patterns with their
//! grouping, symbols, and digits; short compact numbers ("1.2K",
//! "1,2 Mio."); and byte sizes ("1.5 kB", "512 bytes"). Rounding is
//! half-even on the shortest decimal that reads back as the double, as
//! ICU does, so 2.675 is 2.68 at two digits.

const std = @import("std");
const data = @import("cldr_data");
const cldr = @import("cldr.zig");
const plural = @import("plural.zig");

const Writer = std.Io.Writer;
const Locale = cldr.Locale;

/// The most fraction digits a number may show.
pub const max_fraction = 15;

/// A nonnegative decimal number: 0.d[0]d[1]...d[n-1] times 10^point, its
/// digits without leading or trailing zeros (n is 0 for zero).
pub const Decimal = struct {
    d: [40]u8 = undefined,
    n: u8 = 0,
    point: i32 = 0,

    /// |x|'s shortest round-trip decimal; x is finite.
    pub fn fromFloat(x: f64) Decimal {
        var buf: [64]u8 = undefined;
        const s = std.fmt.bufPrint(&buf, "{e}", .{@abs(x)}) catch unreachable;
        const e_at = std.mem.indexOfScalar(u8, s, 'e').?;
        var dec: Decimal = .{};
        for (s[0..e_at]) |ch| if (ch != '.') dec.push(ch - '0');
        dec.point = (std.fmt.parseInt(i32, s[e_at + 1 ..], 10) catch unreachable) + 1;
        dec.trim();
        return dec;
    }

    /// ASCII digits with an optional decimal point: "1.50".
    pub fn parse(s: []const u8) ?Decimal {
        var dec: Decimal = .{};
        var int_len: i32 = 0;
        var seen_point = false;
        if (s.len == 0) return null;
        for (s) |ch| switch (ch) {
            '0'...'9' => {
                if (dec.n == dec.d.len) return null;
                dec.push(ch - '0');
                if (!seen_point) int_len += 1;
            },
            '.' => {
                if (seen_point) return null;
                seen_point = true;
            },
            else => return null,
        };
        // Leading zeros moved the point left of the integer digits.
        dec.point += int_len;
        dec.trim();
        return dec;
    }

    fn push(dec: *Decimal, digit: u8) void {
        // Leading zeros move the point instead.
        if (dec.n == 0 and digit == 0) {
            dec.point -= 1;
            return;
        }
        dec.d[dec.n] = digit;
        dec.n += 1;
    }

    fn trim(dec: *Decimal) void {
        while (dec.n > 0 and dec.d[dec.n - 1] == 0) dec.n -= 1;
        if (dec.n == 0) dec.point = 0;
    }

    pub fn isZero(dec: Decimal) bool {
        return dec.n == 0;
    }

    /// Multiplies by 10^by.
    pub fn shift(dec: *Decimal, by: i32) void {
        if (dec.n > 0) dec.point += by;
    }

    /// The digit for 10^place.
    pub fn digitAt(dec: Decimal, place: i32) u8 {
        const i = dec.point - 1 - place;
        return if (i >= 0 and i < dec.n) dec.d[@intCast(i)] else 0;
    }

    /// Integer digits as written: at least one.
    pub fn intDigits(dec: Decimal) u32 {
        return if (dec.n == 0 or dec.point <= 0) 1 else @intCast(dec.point);
    }

    /// Fraction digits up to the last that is not zero.
    pub fn fractionDigits(dec: Decimal) u32 {
        return @intCast(@max(0, @as(i32, dec.n) - dec.point));
    }

    /// The position of the leading digit: 0 for 1 to 9.99, -1 for 0.1 to
    /// 0.99; 0 for zero.
    pub fn magnitude(dec: Decimal) i32 {
        return if (dec.n == 0) 0 else dec.point - 1;
    }

    /// Rounds half to even to `fraction` digits after the point.
    pub fn round(dec: *Decimal, fraction: u32) void {
        const keep = dec.point + @as(i32, @intCast(fraction));
        if (keep >= dec.n) return;
        if (keep < 0) {
            dec.n = 0;
            dec.point = 0;
            return;
        }
        const k: usize = @intCast(keep);
        const first = dec.d[k];
        const previous_odd = k > 0 and dec.d[k - 1] % 2 == 1;
        const up = first > 5 or (first == 5 and (dec.n > k + 1 or previous_odd));
        dec.n = @intCast(k);
        if (up) {
            var i = k;
            while (true) {
                if (i == 0) {
                    // Every kept digit was 9 (or none was kept): 10^point.
                    dec.d[0] = 1;
                    dec.n = 1;
                    dec.point += 1;
                    break;
                }
                i -= 1;
                if (dec.d[i] < 9) {
                    dec.d[i] += 1;
                    break;
                }
                dec.d[i] = 0;
            }
        }
        dec.trim();
    }
};

pub const Style = enum(u8) {
    /// "1,234.5"
    decimal,
    /// 0.25 is "25%".
    percent,
    /// "1.2K", "12M"
    compact,
    /// "512 bytes", "1.5 kB": decimal units of 1000.
    bytes,
};

pub const Options = struct {
    style: Style = .decimal,
    /// The fewest and most fraction digits (at most max_fraction); null
    /// is the style's: decimal 0 to 3, percent none, compact two
    /// significant digits below 10 and none above, bytes one in kB and
    /// above.
    fraction: ?[2]u8 = null,
    grouping: bool = true,
};

/// Positions of a number record's fields (gen.zig writes them in this
/// order).
const N = struct {
    const decimal: usize = 0;
    const group: usize = 1;
    const percent: usize = 2;
    const minus: usize = 3;
    const plus: usize = 4;
    const infinity: usize = 5;
    const nan: usize = 6;
    const decimal_pattern: usize = 7;
    const percent_pattern: usize = 8;
    const min_grouping: usize = 9;
    const compact: usize = 10;
    const bytes: usize = compact + 12 * 6;
};

comptime {
    std.debug.assert(data.number_field_count == N.bytes + 6 * 6);
}

const none: u16 = 0xffff;

fn field(l: Locale, at: usize) []const u8 {
    const i = l.numbers[at];
    return if (i == none) "" else cldr.poolString(i);
}

/// A decimal or percent pattern's parts ("#,##0.###", "#,##0 %",
/// "%#,#0;%-#,#0").
const Pattern = struct {
    prefix: []const u8 = "",
    suffix: []const u8 = "",
    neg_prefix: ?[]const u8 = null,
    neg_suffix: ?[]const u8 = null,
    /// Group sizes; primary 0 is no grouping.
    primary: u8 = 0,
    secondary: u8 = 0,
    min_int: u8 = 1,
    min_frac: u8 = 0,
    max_frac: u8 = 0,

    fn parse(p: []const u8) Pattern {
        const semi = unquoted(p, ";");
        const pos = split(p[0 .. semi orelse p.len]);
        var pat: Pattern = .{ .prefix = pos.prefix, .suffix = pos.suffix };
        if (semi) |s| {
            const neg = split(p[s + 1 ..]);
            pat.neg_prefix = neg.prefix;
            pat.neg_suffix = neg.suffix;
        }
        const num = pos.number;
        const dot = std.mem.indexOfScalar(u8, num, '.') orelse num.len;
        const int = num[0..dot];
        pat.min_int = @intCast(std.mem.count(u8, int, "0"));
        if (std.mem.lastIndexOfScalar(u8, int, ',')) |last| {
            pat.primary = @intCast(int.len - last - 1);
            pat.secondary = pat.primary;
            if (std.mem.lastIndexOfScalar(u8, int[0..last], ',')) |prev| pat.secondary = @intCast(last - prev - 1);
        }
        if (dot < num.len) {
            const frac = num[dot + 1 ..];
            pat.min_frac = @intCast(std.mem.count(u8, frac, "0"));
            pat.max_frac = @intCast(frac.len);
        }
        return pat;
    }

    /// A subpattern's prefix, number, and suffix.
    fn split(p: []const u8) struct { prefix: []const u8, number: []const u8, suffix: []const u8 } {
        const start = unquoted(p, "#0,.") orelse p.len;
        var end = start;
        while (end < p.len and std.mem.indexOfScalar(u8, "#0,.", p[end]) != null) end += 1;
        return .{ .prefix = p[0..start], .number = p[start..end], .suffix = p[end..] };
    }
};

/// The first byte of `set` outside single quotes.
fn unquoted(p: []const u8, set: []const u8) ?usize {
    var quoted = false;
    for (p, 0..) |ch, i| {
        if (ch == '\'') quoted = !quoted else if (!quoted and std.mem.indexOfScalar(u8, set, ch) != null) return i;
    }
    return null;
}

/// Writes a pattern's prefix or suffix: quotes removed ('' is a quote),
/// % - + as the locale's symbols.
fn writeAffix(l: Locale, w: *Writer, s: []const u8) Writer.Error!void {
    var i: usize = 0;
    var quoted = false;
    while (i < s.len) : (i += 1) {
        const ch = s[i];
        if (ch == '\'') {
            if (i + 1 < s.len and s[i + 1] == '\'') {
                try w.writeByte('\'');
                i += 1;
            } else quoted = !quoted;
            continue;
        }
        if (!quoted) switch (ch) {
            '%' => {
                try w.writeAll(field(l, N.percent));
                continue;
            },
            '-' => {
                try w.writeAll(field(l, N.minus));
                continue;
            },
            '+' => {
                try w.writeAll(field(l, N.plus));
                continue;
            },
            else => {},
        };
        try w.writeByte(ch);
    }
}

/// How a number is written: the digits shown and what goes around them.
const Shown = struct {
    negative: bool = false,
    special: enum { finite, nan, infinity } = .finite,
    dec: Decimal = .{},
    /// Fraction digits written.
    fraction: u32 = 0,
    /// Compact numbers' exponent: "1.2K" is 1.2 times 10^3.
    exponent: u32 = 0,
    /// Group sizes and the fewest integer digits, from the decimal or
    /// percent pattern.
    pattern: Pattern = .{},
    min_grouping: u32 = 1,
    grouping: bool = true,
    affix: union(enum) {
        /// Decimal and percent: the pattern's prefix and suffix.
        pattern,
        /// A compact pattern ("0K", "00 Mio'.'").
        compact: []const u8,
        /// A unit pattern ("{0} kB").
        unit: []const u8,
    } = .pattern,
};

fn roundTo(dec: *Decimal, min: u32, max: u32) u32 {
    dec.round(max);
    return @max(min, dec.fractionDigits());
}

/// The category the number takes, as shown, for patterns by plural
/// category.
fn categoryOf(rules: plural.Rules, s: Shown) plural.Category {
    return rules.category(.cardinal, plural.Operands.init(s.dec, s.fraction, s.exponent));
}

fn compactPattern(l: Locale, magnitude: u32, cat: plural.Category) []const u8 {
    const base = N.compact + (magnitude - 3) * 6;
    const i = l.numbers[base + @intFromEnum(cat)];
    return cldr.poolString(if (i == none) l.numbers[base + 5] else i);
}

fn shown(l: Locale, value: f64, opts: Options) Shown {
    const decimal = Pattern.parse(field(l, N.decimal_pattern));
    var s: Shown = .{
        .negative = std.math.signbit(value) and !std.math.isNan(value),
        .pattern = decimal,
        .min_grouping = l.numbers[N.min_grouping],
        .grouping = opts.grouping,
    };
    if (std.math.isNan(value)) {
        s.special = .nan;
        return s;
    }
    if (opts.style == .percent) s.pattern = Pattern.parse(field(l, N.percent_pattern));
    if (std.math.isInf(value)) {
        s.special = .infinity;
        return s;
    }
    const x = Decimal.fromFloat(value);
    const rules = plural.Rules.find(l.tag);
    switch (opts.style) {
        .decimal, .percent => {
            s.dec = x;
            if (opts.style == .percent) s.dec.shift(2);
            const f: [2]u8 = opts.fraction orelse .{ s.pattern.min_frac, s.pattern.max_frac };
            s.fraction = roundTo(&s.dec, f[0], f[1]);
        },
        .compact => {
            // Compact numbers group from five digits, as ICU's do.
            s.min_grouping = @max(s.min_grouping, 2);
            var mag = x.magnitude();
            var tries: u32 = 0;
            while (true) : (tries += 1) {
                const m: u32 = @intCast(std.math.clamp(mag, 0, 14));
                var scale: i32 = 0;
                if (m >= 3) {
                    const p = compactPattern(l, m, .other);
                    const zeros = std.mem.count(u8, p, "0");
                    // "0" alone: this magnitude is written in full.
                    if (zeros != p.len) scale = @as(i32, @intCast(m)) - @as(i32, @intCast(zeros)) + 1;
                }
                s.dec = x;
                s.dec.shift(-scale);
                const f: [2]u8 = opts.fraction orelse blk: {
                    // Two significant digits below 10, else integers.
                    if (s.dec.intDigits() >= 2) break :blk [2]u8{ 0, 0 };
                    break :blk [2]u8{ 0, @as(u8, @intCast(@min(max_fraction, @max(0, 1 - s.dec.magnitude())))) };
                };
                s.fraction = roundTo(&s.dec, f[0], f[1]);
                s.exponent = @intCast(scale);
                // Rounding up into the next magnitude: 999 950 is 1M,
                // not 1000K.
                const new_mag = s.dec.magnitude() + scale;
                if (!s.dec.isZero() and new_mag > mag and tries == 0) {
                    mag = new_mag;
                    continue;
                }
                if (scale > 0) s.affix = .{ .compact = compactPattern(l, m, categoryOf(rules, s)) };
                break;
            }
        },
        .bytes => {
            var whole = x;
            whole.round(0);
            if (whole.intDigits() <= 3) {
                s.dec = whole;
                s.fraction = 0;
                s.affix = .{ .unit = unitPattern(l, 0, categoryOf(rules, s)) };
                return s;
            }
            // At least kB: 999.6 bytes rounds to 1.0 kB.
            var unit: u32 = @intCast(std.math.clamp(@divFloor(x.magnitude(), 3), 1, 5));
            while (true) {
                s.dec = x;
                s.dec.shift(-3 * @as(i32, @intCast(unit)));
                const f: [2]u8 = opts.fraction orelse .{ 1, 1 };
                s.fraction = roundTo(&s.dec, f[0], f[1]);
                if (s.dec.intDigits() > 3 and unit < 5) {
                    unit += 1;
                    continue;
                }
                break;
            }
            s.affix = .{ .unit = unitPattern(l, unit, categoryOf(rules, s)) };
        },
    }
    // Zero has no sign, even when a negative number rounds to it.
    if (s.dec.isZero()) s.negative = false;
    return s;
}

fn unitPattern(l: Locale, unit: u32, cat: plural.Category) []const u8 {
    const base = N.bytes + unit * 6;
    const i = l.numbers[base + @intFromEnum(cat)];
    return cldr.poolString(if (i == none) l.numbers[base + 5] else i);
}

/// Writes the digits of `s`, grouped, with the decimal separator.
fn writeDigits(l: Locale, w: *Writer, s: Shown) Writer.Error!void {
    const ds = l.digitStrings();
    const p = s.pattern;
    const int_len = @max(s.dec.intDigits(), p.min_int);
    const grouped = s.grouping and p.primary > 0 and int_len >= p.primary + s.min_grouping;
    var place: i32 = @intCast(int_len);
    while (place > 0) {
        place -= 1;
        try w.writeAll(ds[s.dec.digitAt(place)]);
        if (grouped and place > 0 and (place == p.primary or (place > p.primary and p.secondary > 0 and @rem(place - p.primary, p.secondary) == 0)))
            try w.writeAll(field(l, N.group));
    }
    if (s.fraction == 0) return;
    try w.writeAll(field(l, N.decimal));
    var k: i32 = 1;
    while (k <= s.fraction) : (k += 1) try w.writeAll(ds[s.dec.digitAt(-k)]);
}

/// Writes `value` as the locale does.
pub fn format(l: Locale, w: *Writer, value: f64, opts: Options) Writer.Error!void {
    const s = shown(l, value, opts);
    if (s.special == .nan) return w.writeAll(field(l, N.nan));
    switch (s.affix) {
        .pattern => {
            const p = s.pattern;
            if (s.negative) {
                if (p.neg_prefix) |np| try writeAffix(l, w, np) else {
                    try w.writeAll(field(l, N.minus));
                    try writeAffix(l, w, p.prefix);
                }
            } else try writeAffix(l, w, p.prefix);
            if (s.special == .infinity) try w.writeAll(field(l, N.infinity)) else try writeDigits(l, w, s);
            try writeAffix(l, w, if (s.negative) p.neg_suffix orelse p.suffix else p.suffix);
        },
        .compact => |cp| {
            if (s.negative) try w.writeAll(field(l, N.minus));
            const start = std.mem.indexOfScalar(u8, cp, '0').?;
            var end = start;
            while (end < cp.len and cp[end] == '0') end += 1;
            try writeAffix(l, w, cp[0..start]);
            try writeDigits(l, w, s);
            try writeAffix(l, w, cp[end..]);
        },
        .unit => |up| {
            const at = std.mem.indexOf(u8, up, "{0}") orelse up.len;
            try w.writeAll(up[0..at]);
            if (s.negative) try w.writeAll(field(l, N.minus));
            try writeDigits(l, w, s);
            if (at < up.len) try w.writeAll(up[at + 3 ..]);
        },
    }
}

/// The plural category, in `rules`, of `value` as `format` writes it with
/// `opts`: in English 1 is one but "1.0" other, and "1.5 kB" is other.
/// The rules are passed apart from the locale since CLDR has rules for
/// languages it has no number data for (Manx, say, written with
/// English's).
pub fn category(l: Locale, rules: plural.Rules, kind: plural.Kind, value: f64, opts: Options) plural.Category {
    const s = shown(l, value, opts);
    if (s.special != .finite) return .other;
    return rules.category(kind, plural.Operands.init(s.dec, s.fraction, s.exponent));
}

/// Reads a number written as `format` writes decimals, or typed with
/// ASCII digits: the locale's digits, decimal separator, group
/// separators (ignored), and minus sign; bidirectional marks are
/// ignored. Null if it is not a number.
pub fn parse(l: Locale, text: []const u8) ?f64 {
    const ds = l.digitStrings();
    const dec_sym = field(l, N.decimal);
    const group_sym = field(l, N.group);
    const minus = std.mem.trim(u8, field(l, N.minus), "\u{200E}\u{200F}\u{061C}");
    var ascii: [128]u8 = undefined;
    var n: usize = 0;
    var i: usize = 0;
    const t = std.mem.trim(u8, text, " \t");
    outer: while (i < t.len) {
        if (n == ascii.len) return null;
        const rest = t[i..];
        for ([_][]const u8{ "\u{200E}", "\u{200F}", "\u{061C}" }) |mark| if (std.mem.startsWith(u8, rest, mark)) {
            i += mark.len;
            continue :outer;
        };
        for (ds, 0..) |d, k| if (std.mem.startsWith(u8, rest, d)) {
            ascii[n] = '0' + @as(u8, @intCast(k));
            n += 1;
            i += d.len;
            continue :outer;
        };
        if (std.mem.startsWith(u8, rest, dec_sym)) {
            ascii[n] = '.';
            n += 1;
            i += dec_sym.len;
            continue;
        }
        if (std.mem.startsWith(u8, rest, group_sym)) {
            i += group_sym.len;
            continue;
        }
        for ([_][]const u8{ minus, "-", "\u{2212}" }) |m| if (m.len > 0 and std.mem.startsWith(u8, rest, m)) {
            ascii[n] = '-';
            n += 1;
            i += m.len;
            continue :outer;
        };
        const ch = rest[0];
        switch (ch) {
            '0'...'9', '+', 'e', 'E' => ascii[n] = ch,
            // An ASCII point is the decimal separator where it is not the
            // group separator.
            '.' => ascii[n] = '.',
            // Commas and spaces that are not the locale's separators
            // group.
            ',', ' ' => {
                i += 1;
                continue;
            },
            else => {
                // No-break spaces likewise.
                for ([_][]const u8{ "\u{00A0}", "\u{202F}" }) |sp| if (std.mem.startsWith(u8, rest, sp)) {
                    i += sp.len;
                    continue :outer;
                };
                return null;
            },
        }
        n += 1;
        i += 1;
    }
    if (n == 0) return null;
    // Only plain numbers: no "inf", "nan", or hexadecimal.
    for (ascii[0..n]) |ch| if (std.mem.indexOfScalar(u8, "0123456789.-+eE", ch) == null) return null;
    const v = std.fmt.parseFloat(f64, ascii[0..n]) catch return null;
    return if (std.math.isFinite(v)) v else null;
}

// Tests ------------------------------------------------------------------------

const testing = std.testing;

fn fmt(tag: []const u8, value: f64, opts: Options) ![]const u8 {
    const S = struct {
        var buf: [256]u8 = undefined;
    };
    var w: Writer = .fixed(&S.buf);
    try format(Locale.find(tag), &w, value, opts);
    return w.buffered();
}

test "decimals: rounding half to even on the shortest decimal" {
    var d = Decimal.fromFloat(2.675);
    d.round(2);
    try testing.expectEqual(@as(u8, 8), d.digitAt(-2));
    try testing.expectEqualStrings("2.68", try fmt("en", 2.675, .{ .fraction = .{ 2, 2 } }));
    try testing.expectEqualStrings("0.12", try fmt("en", 0.125, .{ .fraction = .{ 0, 2 } }));
    try testing.expectEqualStrings("0.38", try fmt("en", 0.375, .{ .fraction = .{ 0, 2 } }));
    try testing.expectEqualStrings("2", try fmt("en", 2.5, .{ .fraction = .{ 0, 0 } }));
    try testing.expectEqualStrings("4", try fmt("en", 3.5, .{ .fraction = .{ 0, 0 } }));
    try testing.expectEqualStrings("1,000", try fmt("en", 999.9996, .{}));
    try testing.expectEqualStrings("0", try fmt("en", 0.0004, .{}));
    try testing.expectEqualStrings("0", try fmt("en", -0.0004, .{}));
    try testing.expectEqualStrings("1", try fmt("en", 0.6, .{ .fraction = .{ 0, 0 } }));
    try testing.expectEqualStrings("0.00", try fmt("en", 0, .{ .fraction = .{ 2, 2 } }));
    try testing.expectEqualStrings("1,000,000,000,000,000,000,000", try fmt("en", 1e21, .{}));
}

test "decimal and percent patterns: grouping, symbols, digits" {
    try testing.expectEqualStrings("1,234,567.891", try fmt("en", 1234567.891, .{}));
    try testing.expectEqualStrings("-1,234.5", try fmt("en", -1234.5, .{}));
    try testing.expectEqualStrings("1.234.567,891", try fmt("de", 1234567.891, .{}));
    try testing.expectEqualStrings("1234567.891", try fmt("en", 1234567.891, .{ .grouping = false }));
    // Indian grouping: 3, then 2.
    try testing.expectEqualStrings("12,34,567", try fmt("hi", 1234567, .{}));
    // Spanish groups from five digits (minimumGroupingDigits 2).
    try testing.expectEqualStrings("1234", try fmt("es", 1234, .{}));
    try testing.expectEqualStrings("12.345", try fmt("es", 12345, .{}));
    try testing.expectEqualStrings("1\u{202F}234,5", try fmt("fr", 1234.5, .{}));
    try testing.expectEqualStrings("1'234.5", try fmt("de-CH", 1234.5, .{}));
    // Egyptian Arabic: Arabic-Indic digits and separators, and the
    // Arabic letter mark before the minus.
    try testing.expectEqualStrings("\u{061C}-١٬٢٣٤٫٥", try fmt("ar-EG", -1234.5, .{}));
    try testing.expectEqualStrings("25%", try fmt("en", 0.25, .{ .style = .percent }));
    try testing.expectEqualStrings("12,5\u{00A0}%", try fmt("de", 0.125, .{ .style = .percent, .fraction = .{ 1, 1 } }));
    try testing.expectEqualStrings("%25", try fmt("tr", 0.25, .{ .style = .percent }));
    try testing.expectEqualStrings("-%25", try fmt("tr", -0.25, .{ .style = .percent }));
    try testing.expectEqualStrings("٢٥٪\u{061C}", try fmt("ar-EG", 0.25, .{ .style = .percent }));
    try testing.expectEqualStrings("1.50", try fmt("en", 1.5, .{ .fraction = .{ 2, 3 } }));
    try testing.expectEqualStrings("NaN", try fmt("en", std.math.nan(f64), .{}));
    try testing.expectEqualStrings("-∞", try fmt("en", -std.math.inf(f64), .{}));
}

test "compact numbers" {
    try testing.expectEqualStrings("999", try fmt("en", 999, .{ .style = .compact }));
    try testing.expectEqualStrings("1.2K", try fmt("en", 1234, .{ .style = .compact }));
    try testing.expectEqualStrings("12K", try fmt("en", 12345, .{ .style = .compact }));
    try testing.expectEqualStrings("123K", try fmt("en", 123456, .{ .style = .compact }));
    try testing.expectEqualStrings("1M", try fmt("en", 999950, .{ .style = .compact }));
    try testing.expectEqualStrings("-1.5B", try fmt("en", -1.5e9, .{ .style = .compact }));
    try testing.expectEqualStrings("1.2", try fmt("en", 1.234, .{ .style = .compact }));
    try testing.expectEqualStrings("1000T", try fmt("en", 1e15, .{ .style = .compact }));
    // German writes thousands in full, grouped from five digits.
    try testing.expectEqualStrings("1234", try fmt("de", 1234, .{ .style = .compact }));
    try testing.expectEqualStrings("12.345", try fmt("de", 12345, .{ .style = .compact }));
    try testing.expectEqualStrings("1,2\u{00A0}Mio.", try fmt("de", 1.2e6, .{ .style = .compact }));
    try testing.expectEqualStrings("1,2\u{00A0}тыс.", try fmt("ru", 1234, .{ .style = .compact }));
    try testing.expectEqualStrings("1.23K", try fmt("en", 1234, .{ .style = .compact, .fraction = .{ 2, 2 } }));
    try testing.expectEqualStrings("1万", try fmt("ja", 10000, .{ .style = .compact }));
    try testing.expectEqualStrings("1234", try fmt("ja", 1234, .{ .style = .compact }));
}

test "byte sizes" {
    try testing.expectEqualStrings("1 byte", try fmt("en", 1, .{ .style = .bytes }));
    try testing.expectEqualStrings("999 bytes", try fmt("en", 999, .{ .style = .bytes }));
    try testing.expectEqualStrings("1.5 kB", try fmt("en", 1500, .{ .style = .bytes }));
    try testing.expectEqualStrings("53.2 kB", try fmt("en", 53_200, .{ .style = .bytes }));
    try testing.expectEqualStrings("2.0 GB", try fmt("en", 2e9, .{ .style = .bytes }));
    try testing.expectEqualStrings("1.0 MB", try fmt("en", 999_999, .{ .style = .bytes }));
    try testing.expectEqualStrings("1.0 kB", try fmt("en", 999.6, .{ .style = .bytes }));
    try testing.expectEqualStrings("2 GB", try fmt("en", 2e9, .{ .style = .bytes, .fraction = .{ 0, 1 } }));
    try testing.expectEqualStrings("1,500.0 PB", try fmt("en", 1.5e18, .{ .style = .bytes }));
    try testing.expectEqualStrings("1,5\u{202F}ko", try fmt("fr", 1500, .{ .style = .bytes }));
    try testing.expectEqualStrings("1\u{00A0}octet", try fmt("fr", 1, .{ .style = .bytes }));
    // Russian: the long forms' categories.
    try testing.expectEqualStrings("1 байт", try fmt("ru", 1, .{ .style = .bytes }));
    try testing.expectEqualStrings("2 байта", try fmt("ru", 2, .{ .style = .bytes }));
    try testing.expectEqualStrings("5 байт", try fmt("ru", 5, .{ .style = .bytes }));
    try testing.expectEqualStrings("١٫٥ كيلوبايت", try fmt("ar-EG", 1500, .{ .style = .bytes }));
}

fn categoryIn(tag: []const u8, kind: plural.Kind, value: f64, opts: Options) plural.Category {
    return category(Locale.find(tag), plural.Rules.find(tag), kind, value, opts);
}

test "categories of numbers as written" {
    try testing.expectEqual(plural.Category.one, categoryIn("en", .cardinal, 1, .{}));
    try testing.expectEqual(plural.Category.other, categoryIn("en", .cardinal, 1, .{ .fraction = .{ 1, 1 } }));
    // 1.0004 shows as "1": one.
    try testing.expectEqual(plural.Category.one, categoryIn("en", .cardinal, 1.0004, .{}));
    try testing.expectEqual(plural.Category.few, categoryIn("en", .ordinal, 23, .{}));
    try testing.expectEqual(plural.Category.other, categoryIn("en", .ordinal, 13, .{}));
    // French compact millions: "1 M" is many (1c6).
    try testing.expectEqual(plural.Category.many, categoryIn("fr", .cardinal, 1e6, .{ .style = .compact }));
    try testing.expectEqual(plural.Category.many, categoryIn("fr", .cardinal, 1e6, .{}));
    try testing.expectEqual(plural.Category.other, categoryIn("fr", .cardinal, 1000, .{ .style = .compact }));
    try testing.expectEqual(plural.Category.few, categoryIn("ru", .cardinal, 22, .{}));
    try testing.expectEqual(plural.Category.other, categoryIn("en", .cardinal, std.math.nan(f64), .{}));
    // Manx has plural rules but no number data of its own.
    try testing.expectEqualStrings("en", Locale.find("gv").tag);
    try testing.expectEqual(plural.Category.two, categoryIn("gv", .cardinal, 12, .{}));
}

test "parsing numbers as written" {
    try testing.expectEqual(@as(?f64, 1234.5), parse(Locale.find("en"), "1,234.5"));
    try testing.expectEqual(@as(?f64, 1234.5), parse(Locale.find("de"), "1.234,5"));
    try testing.expectEqual(@as(?f64, 1234.5), parse(Locale.find("de"), "1234,5"));
    try testing.expectEqual(@as(?f64, -1234.5), parse(Locale.find("ar-EG"), "\u{061C}-١٬٢٣٤٫٥"));
    try testing.expectEqual(@as(?f64, 12.5), parse(Locale.find("ar-EG"), "12.5"));
    try testing.expectEqual(@as(?f64, 1234.5), parse(Locale.find("fr"), "1\u{202F}234,5"));
    try testing.expectEqual(@as(?f64, -3), parse(Locale.find("en"), "\u{2212}3"));
    try testing.expectEqual(@as(?f64, null), parse(Locale.find("en"), "inf"));
    try testing.expectEqual(@as(?f64, null), parse(Locale.find("en"), "12 apples"));
    try testing.expectEqual(@as(?f64, null), parse(Locale.find("en"), ""));
}
